export const appDockerfile = "FROM node:24-alpine AS base\n\nFROM base AS deps\nWORKDIR /app\nCOPY package.json package-lock.json ./\nRUN npm ci\n\nFROM base AS builder\nWORKDIR /app\nCOPY --from=deps /app/node_modules ./node_modules\nCOPY . .\nRUN npm run build\n\nFROM base AS runner\nWORKDIR /app\nENV NODE_ENV=production\nRUN addgroup --system --gid 1001 nodejs && adduser --system --uid 1001 nextjs\n# O standalone só precisa de Node; não transportar gestores de pacotes para o runtime.\nRUN rm -rf /usr/local/lib/node_modules/npm /usr/local/lib/node_modules/corepack /opt/yarn-* \\\n    && rm -f /usr/local/bin/npm /usr/local/bin/npx /usr/local/bin/corepack /usr/local/bin/yarn /usr/local/bin/yarnpkg\nCOPY --from=builder --chown=nextjs:nodejs /app/.next/standalone ./\nCOPY --from=builder --chown=nextjs:nodejs /app/.next/static ./.next/static\nUSER nextjs\nEXPOSE 3000\nENV PORT=3000\nENV HOSTNAME=0.0.0.0\nHEALTHCHECK --interval=30s --timeout=5s --start-period=20s --retries=3 \\\n  CMD node -e \"fetch('http://127.0.0.1:3000').then((r)=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))\"\nCMD [\"node\", \"server.js\"]\n";

export const postgresBackupScript = "#!/usr/bin/env bash\nset -euo pipefail\numask 077\n\nBACKUP_DIR=\"${BACKUP_DIR:-/srv/db/backups}\"\nPOSTGRES_CONTAINER=\"${POSTGRES_CONTAINER:-postgres}\"\nPOSTGRES_USER=\"${POSTGRES_USER:-exemplo1}\"\nRETENTION_DAYS=\"${RETENTION_DAYS:-14}\"\n[[ \"$RETENTION_DAYS\" =~ ^[1-9][0-9]*$ ]] || {\n  printf 'RETENTION_DAYS tem de ser um inteiro positivo\\n' >&2\n  exit 1\n}\n\nmkdir -p \"$BACKUP_DIR\"\ntimestamp=$(date -u +%Y%m%d_%H%M%S)\narchive=\"$BACKUP_DIR/all_databases_${timestamp}_$$.sql.gz\"\ntemporary=$(mktemp \"$BACKUP_DIR/.backup.XXXXXX\")\ntrap 'if [[ -n \"$temporary\" ]]; then rm -f -- \"$temporary\"; fi' EXIT\n\n# Sem TTY: uma falha do dump tem de fazer falhar toda a pipeline.\ndocker exec \"$POSTGRES_CONTAINER\" pg_dumpall -U \"$POSTGRES_USER\" --no-password \\\n  | gzip > \"$temporary\"\ngzip -t \"$temporary\"\n[[ \"$(gzip -cd \"$temporary\" | wc -c)\" -gt 0 ]] || {\n  printf 'O dump está vazio; backup rejeitado\\n' >&2\n  exit 1\n}\n\nmv -- \"$temporary\" \"$archive\"\ntemporary=\"\"\n# Só aplicar retenção depois de publicar um backup com sucesso.\nfind \"$BACKUP_DIR\" -type f -name 'all_databases_*.sql.gz' \\\n  -mtime \"+$RETENTION_DAYS\" -delete\nprintf 'Backup concluído: %s\\n' \"$archive\"\n";

export const postgresRestoreScript = "#!/usr/bin/env bash\nset -euo pipefail\n\narchive=\"${1:?Indica o caminho do backup .sql.gz}\"\nimage=\"${POSTGRES_IMAGE:-postgres:16-alpine}\"\n[[ -f \"$archive\" ]] || { printf 'Backup inexistente\\n' >&2; exit 1; }\ngzip -t \"$archive\"\n\n# Contentor descartável, sem rede, portas ou volumes do servidor original.\nname=\"postgres-restore-check-$(date -u +%Y%m%d%H%M%S)-$$\"\ncleanup() { docker rm --force --volumes \"$name\" >/dev/null 2>&1 || true; }\ntrap cleanup EXIT\ndocker run --detach --name \"$name\" --network none --memory 1g --cpus 1 \\\n  --env POSTGRES_USER=restore_check_admin \\\n  --env POSTGRES_HOST_AUTH_METHOD=trust \"$image\" >/dev/null\n\nready=false\nfor ((attempt = 0; attempt < 60; attempt++)); do\n  if docker exec \"$name\" pg_isready -U restore_check_admin -d postgres >/dev/null 2>&1; then\n    ready=true\n    break\n  fi\n  sleep 1\ndone\n[[ \"$ready\" == true ]] || { printf 'PostgreSQL de teste indisponível\\n' >&2; exit 1; }\n\ngzip -cd \"$archive\" | docker exec -i \"$name\" \\\n  psql -X -v ON_ERROR_STOP=1 -U restore_check_admin -d postgres >/dev/null\ndocker exec \"$name\" psql -X -v ON_ERROR_STOP=1 -U restore_check_admin \\\n  -d postgres -c 'SELECT datname FROM pg_database WHERE NOT datistemplate;'\nprintf 'Restauro de teste concluído no contentor descartável\\n'\n";

export const postgresCompose = "services:\n  postgres:\n    image: postgres:16-alpine\n    container_name: postgres\n    restart: unless-stopped\n    environment:\n      POSTGRES_DB: exemplo1\n      POSTGRES_USER: exemplo1\n      POSTGRES_PASSWORD_FILE: /run/secrets/postgres_password\n    secrets:\n      - postgres_password\n    ports:\n      - \"127.0.0.1:5432:5432\"\n    volumes:\n      - ./data:/var/lib/postgresql/data\n    networks:\n      - data\n    mem_limit: 1g\n    cpus: 1.0\n    healthcheck:\n      test: [\"CMD\", \"pg_isready\", \"-U\", \"exemplo1\", \"-d\", \"exemplo1\"]\n      interval: 10s\n      timeout: 5s\n      retries: 5\n      start_period: 20s\n\nsecrets:\n  postgres_password:\n    file: /srv/secrets/postgres_password\n\nnetworks:\n  data:\n    external: true\n";

export const appCompose = "services:\n  app:\n    image: ghcr.io/UTILIZADOR_GITHUB/nome-app:${TAG:?Define TAG com o SHA completo publicado no GHCR}\n    container_name: nome-app\n    restart: unless-stopped\n    init: true\n    environment:\n      HOSTNAME: 0.0.0.0\n    mem_limit: 512m\n    cpus: 1.0\n    security_opt:\n      - no-new-privileges:true\n    cap_drop:\n      - ALL\n    networks:\n      - apps\n    healthcheck:\n      test: [\"CMD\", \"node\", \"-e\", \"fetch('http://127.0.0.1:3000').then(r=>process.exit(r.ok?0:1)).catch(()=>process.exit(1))\"]\n      interval: 10s\n      timeout: 5s\n      retries: 5\n      start_period: 20s\n    logging:\n      driver: json-file\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n\nnetworks:\n  apps:\n    external: true\n";

export const laboratoryWorkflow = "name: Build e deployment do laboratório\n\non:\n  push:\n    branches: [main]\n\nconcurrency:\n  group: laboratorio-${{ github.ref }}\n  cancel-in-progress: false\n\npermissions:\n  contents: read\n\nenv:\n  IMAGE_NAME: ghcr.io/UTILIZADOR_GITHUB/nome-app\n\njobs:\n  build:\n    runs-on: ubuntu-latest\n    permissions:\n      contents: read\n      packages: write\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          persist-credentials: false\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"24\"\n          cache: npm\n      - run: npm ci\n      - run: npm run lint\n      - run: npm run build\n      - uses: docker/setup-buildx-action@v3\n      - uses: docker/build-push-action@v6\n        with:\n          context: .\n          load: true\n          tags: ${{ env.IMAGE_NAME }}:${{ github.sha }}\n      - name: Testar o arranque da imagem\n        run: |\n          docker run -d --name lab-smoke --memory 512m --cpus 1 \"$IMAGE_NAME:$GITHUB_SHA\"\n          for _ in $(seq 1 60); do\n            status=$(docker inspect --format '{{.State.Health.Status}}' lab-smoke)\n            if [ \"$status\" = healthy ]; then exit 0; fi\n            if [ \"$status\" = unhealthy ]; then exit 1; fi\n            sleep 2\n          done\n          exit 1\n      - name: Verificar vulnerabilidades\n        uses: aquasecurity/trivy-action@v0.36.0\n        with:\n          image-ref: ${{ env.IMAGE_NAME }}:${{ github.sha }}\n          version: v0.76.2\n          severity: HIGH,CRITICAL\n          exit-code: \"1\"\n          ignore-unfixed: false\n      - name: Remover contentor de teste\n        if: always()\n        run: docker rm -f lab-smoke\n      - uses: docker/login-action@v3\n        with:\n          registry: ghcr.io\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n      - name: Publicar a imagem validada\n        run: docker push \"$IMAGE_NAME:$GITHUB_SHA\"\n\n  deploy:\n    needs: build\n    runs-on: self-hosted\n    environment: laboratorio\n    permissions:\n      contents: read\n      packages: read\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          persist-credentials: false\n      - uses: docker/login-action@v3\n        with:\n          registry: ghcr.io\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n      - name: Guardar a versão anterior e atualizar\n        env:\n          TAG: ${{ github.sha }}\n          SMOKE_URL: ${{ vars.SMOKE_URL }}\n        run: |\n          set -euo pipefail\n          target=/srv/apps/nome-app\n          mkdir -p \"$target\"\n          if [ -f \"$target/docker-compose.yml\" ]; then\n            cp \"$target/docker-compose.yml\" \"$target/docker-compose.previous.yml\"\n            container=$(docker ps -aq --filter 'name=^/nome-app$')\n            if [ -n \"$container\" ]; then\n              docker inspect --format '{{.Config.Image}}' \"$container\" > \"$target/previous-image.txt\"\n            fi\n          fi\n          cp docker-compose.production.yml \"$target/docker-compose.yml\"\n          cd \"$target\"\n          docker compose config --quiet\n          docker compose pull\n          docker compose up --wait --wait-timeout 120 --remove-orphans\n          if [ -n \"$SMOKE_URL\" ]; then\n            curl --fail --silent --show-error --retry 5 --retry-all-errors \\\n              --retry-delay 2 --connect-timeout 5 --max-time 15 \"$SMOKE_URL\" > /dev/null\n          else\n            printf 'Primeiro deploy: verificar o URL após configurar o proxy na fase 10\\n'\n          fi\n      - name: Terminar sessão do registry\n        if: always()\n        run: docker logout ghcr.io\n";
